using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;
using System.Drawing;
namespace Astera {
sealed class GameScanResult {internal readonly List<CustomGame> Games=new List<CustomGame>();internal int Skipped;internal bool Limited;}
static class BatchGames {
    static readonly Regex Helper=new Regex(@"(?i)^(?:unins\d*|uninstall.*|setup.*|install(?:er)?(?:[._ -].*)?|update(?:r)?(?:[._ -].*)?|.*[._ -]updater|UnityCrashHandler.*|crashpad_handler|.*crashreport.*|.*crashhandler.*|CrashReportClient.*|dxsetup|vcredist.*|vc_redist.*|dotnet.*|python(?:w|[0-9.]+w?)?|.*\.console|ffmpeg|ffprobe|7z.*|.*helper|notification_helper|cef.*|chrome.*|UnityPlayer|godot.*(?:editor|console))$",RegexOptions.Compiled);
    static readonly HashSet<string> SkipFolders=new HashSet<string>(new[]{".git",".itch","node_modules","redist","_commonredist","directx","vcredist","dotnet","monobleedingedge","_installer","engine","windows","$recycle.bin","system volume information"},StringComparer.OrdinalIgnoreCase);
    internal static bool CandidateName(string path){return Path.GetExtension(path).Equals(".exe",StringComparison.OrdinalIgnoreCase)&&!Helper.IsMatch(Path.GetFileNameWithoutExtension(path));}
    internal static bool Same(CustomGame a,CustomGame b){if(!String.IsNullOrEmpty(a.Platform)&&a.Platform==b.Platform&&a.PlatformId==b.PlatformId)return true;string x=Path.GetFullPath(a.Executable).TrimEnd(Path.DirectorySeparatorChar),y=Path.GetFullPath(b.Executable).TrimEnd(Path.DirectorySeparatorChar);if(x.Equals(y,StringComparison.OrdinalIgnoreCase))return true;if(!String.IsNullOrEmpty(a.Platform)&&String.IsNullOrEmpty(b.Platform))return y.StartsWith(x+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase);if(String.IsNullOrEmpty(a.Platform)&&!String.IsNullOrEmpty(b.Platform))return x.StartsWith(y+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase);return false;}
    internal static GameScanResult Scan(IEnumerable<string> inputs,IEnumerable<InstalledGame> steam,CancellationToken cancel){
        var result=new GameScanResult();var known=steam.Select(g=>new InstalledGame{Name=g.Name,Platform=g.Platform,Id=g.Id,Folder=Path.GetFullPath(g.Folder)}).ToArray();var queue=new Queue<string>();var visited=new HashSet<string>(StringComparer.OrdinalIgnoreCase);int files=0;
        Action<CustomGame> add=delegate(CustomGame game){if(!result.Games.Any(g=>Same(g,game)))result.Games.Add(game);};
        Action<string> executable=delegate(string path){if(!CandidateName(path)){result.Skipped++;return;}try{path=CustomGames.Validate(path);var platform=known.Where(g=>path.StartsWith(g.Folder.TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)).OrderByDescending(g=>g.Folder.Length).FirstOrDefault();if(platform!=null){add(new CustomGame{Name=platform.Name,Executable=platform.Folder,Platform="steam",PlatformId=platform.Id});return;}string name=Path.GetFileNameWithoutExtension(path);var info=FileVersionInfo.GetVersionInfo(path);if(Regex.IsMatch((info.FileDescription??"")+" "+(info.ProductName??""),@"(?i)\b(uninstaller|crash handler|crash reporter|redistributable|setup wizard|update service)\b")){result.Skipped++;return;}if(!String.IsNullOrWhiteSpace(info.ProductName)&&info.ProductName.Length<=100&&!info.ProductName.Any(Char.IsControl))name=info.ProductName;add(new CustomGame{Name=name,Executable=path});}catch(IOException){result.Skipped++;}catch(UnauthorizedAccessException){result.Skipped++;}catch(System.ComponentModel.Win32Exception){result.Skipped++;}};
        foreach(string input in inputs){cancel.ThrowIfCancellationRequested();if(File.Exists(input))executable(input);else if(Directory.Exists(input))queue.Enqueue(Path.GetFullPath(input));}
        while(queue.Count>0){cancel.ThrowIfCancellationRequested();string folder=queue.Dequeue();if(!visited.Add(folder))continue;if(visited.Count>3000||files>30000||result.Games.Count>=2000){result.Limited=true;break;}try{if((File.GetAttributes(folder)&FileAttributes.ReparsePoint)!=0){result.Skipped++;continue;}var installed=known.FirstOrDefault(g=>folder.Equals(g.Folder,StringComparison.OrdinalIgnoreCase));if(installed!=null){add(new CustomGame{Name=installed.Name,Executable=installed.Folder,Platform="steam",PlatformId=installed.Id});continue;}var receipt=ItchMetadata.Read(folder);if(receipt!=null){add(new CustomGame{Name=receipt.title,Executable=folder,Platform="itch",PlatformId=receipt.id.ToString()});continue;}foreach(string path in Directory.EnumerateFiles(folder,"*.exe")){cancel.ThrowIfCancellationRequested();files++;executable(path);}foreach(string child in Directory.EnumerateDirectories(folder)){if(!SkipFolders.Contains(Path.GetFileName(child)))queue.Enqueue(child);}}catch(IOException){result.Skipped++;}catch(UnauthorizedAccessException){result.Skipped++;}catch(ArgumentException){result.Skipped++;}}
        result.Games.Sort((a,b)=>StringComparer.OrdinalIgnoreCase.Compare(a.Name,b.Name));return result;
    }
    internal static List<CustomGame> NewSelections(IEnumerable<CustomGame> existing,IEnumerable<CustomGame> selected){var result=new List<CustomGame>();foreach(var game in selected){if(existing.Any(g=>Same(g,game))||result.Any(g=>Same(g,game)))continue;var copy=new CustomGame{Name=game.Name,Executable=game.Executable,Platform=game.Platform,PlatformId=game.PlatformId};CustomGames.Set(result,copy,copy.Name,copy.Executable);result.Add(copy);}return result;}
}
sealed partial class LibraryForm {
    void AddGamesFolder(){if(busy)return;using(var picker=new ExplorerFolderDialog{Description="Choose a folder containing your games",SelectedPath=store.Settings.GameScanRoot})if(picker.ShowDialog(this)==DialogResult.OK){store.Settings.GameScanRoot=picker.SelectedPath;store.Save();ReviewBatchGames(new[]{picker.SelectedPath});}}
    void EnableGameFolderDrop(Control control){control.AllowDrop=true;control.DragEnter+=delegate(object sender,DragEventArgs e){if(!busy&&e.Data.GetDataPresent(DataFormats.FileDrop))e.Effect=DragDropEffects.Copy;};control.DragDrop+=delegate(object sender,DragEventArgs e){var files=e.Data.GetData(DataFormats.FileDrop) as string[];if(!busy&&files!=null)ReviewBatchGames(files);};}
    void ReviewBatchGames(string[] paths){using(var dialog=new AsteraDialog{Text="Add games from a folder",Size=new Size(860,600),StartPosition=FormStartPosition.CenterParent})using(var stop=new CancellationTokenSource()){
        var content=new Panel{Dock=DockStyle.Fill,Padding=new Padding(18)};var help=new Label{Dock=DockStyle.Top,Height=52,Text="Scanning for games…",ForeColor=Color.LightSteelBlue};var list=new ListView{Dock=DockStyle.Fill,View=View.Details,CheckBoxes=true,FullRowSelect=true,BackColor=Base,ForeColor=Color.White,BorderStyle=BorderStyle.None};list.OwnerDraw=true;list.DrawColumnHeader+=delegate(object sender,DrawListViewColumnHeaderEventArgs e){using(var brush=new SolidBrush(Color.FromArgb(27,35,55)))e.Graphics.FillRectangle(brush,e.Bounds);TextRenderer.DrawText(e.Graphics,e.Header.Text,list.Font,e.Bounds,Color.White,TextFormatFlags.Left|TextFormatFlags.VerticalCenter);};list.DrawItem+=delegate(object sender,DrawListViewItemEventArgs e){e.DrawDefault=true;};list.DrawSubItem+=delegate(object sender,DrawListViewSubItemEventArgs e){e.DrawDefault=true;};list.Columns.Add("Game",240);list.Columns.Add("Source",80);list.Columns.Add("Location",450);var footer=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=54,Padding=new Padding(0,10,0,0)};var add=Button("Add selected games",delegate{try{var selected=list.CheckedItems.Cast<ListViewItem>().Select(i=>(CustomGame)i.Tag);var added=BatchGames.NewSelections(store.Settings.CustomGames,selected);if(added.Count==0){help.Text="Those games are already in your library, or none were selected.";return;}var prior=store.Settings.CustomGames;store.Settings.CustomGames=prior.Concat(added).ToList();try{store.Save();}catch{store.Settings.CustomGames=prior;throw;}ReloadGames(added[0]);RefreshView();foreach(var game in added)QueuePlatformArtwork(game);dialog.DialogResult=DialogResult.OK;dialog.Close();}catch(Exception error){MessageBox.Show(dialog,error.Message,"Add games");}});add.Enabled=false;var all=Button("Select all",delegate{foreach(ListViewItem item in list.Items)item.Checked=true;});var none=Button("Select none",delegate{foreach(ListViewItem item in list.Items)item.Checked=false;});var cancelScan=Button("Cancel",delegate{stop.Cancel();dialog.Close();});footer.Controls.AddRange(new Control[]{add,all,none,cancelScan});content.Controls.Add(list);content.Controls.Add(help);content.Controls.Add(footer);dialog.Controls.Add(content);dialog.FormClosing+=delegate{stop.Cancel();};dialog.Shown+=async delegate{try{var result=await Task.Run(()=>BatchGames.Scan(paths,PlatformLibraries.Steam(SteamArtwork.Roots()),stop.Token));if(dialog.IsDisposed||stop.IsCancellationRequested)return;foreach(var game in result.Games){bool duplicate=store.Settings.CustomGames.Any(g=>BatchGames.Same(g,game));var item=new ListViewItem(game.Name){Tag=game,Checked=!duplicate};item.SubItems.Add(game.Platform==""?"EXE":game.Platform);item.SubItems.Add(game.Executable);list.Items.Add(item);}help.Text=result.Games.Count+" games found. Review the selection before adding."+(result.Limited?" Scan limit reached; choose a smaller folder to find the rest.":"");add.Enabled=result.Games.Count>0;}catch(OperationCanceledException){}catch(Exception error){if(!dialog.IsDisposed)help.Text="Could not scan this folder: "+error.Message;}};dialog.ShowDialog(this);
    }}
}
}
